function dataTable(t,h,r,opts=['全部']){let f=r.filter(x=>x.join(' ').toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='全部'||x.join(' ').includes(state.filter)));if(state.sort)f.reverse();let max=Math.max(1,Math.ceil(f.length/5));state.page=Math.min(state.page,max);return panel(t,`<div class="filters">${icon('search')}<input id="table-search" aria-label="搜索列表" placeholder="搜索名称、实体或 ID…" value="${esc(state.query)}"><select id="table-filter" aria-label="筛选">${opts.map(o=>`<option ${state.filter===o?'selected':''}>${o}</option>`).join('')}</select>${btn('清除','clear','slim')}<span class="right muted">${state.time} · ${state.tenant}</span></div>`+table(h,f.slice((state.page-1)*5,state.page*5))+`<div class="tablefoot"><span>${f.length} 条演示记录 · 支持列排序</span><div class="actions">${btn('上一页','prev','slim')}<span>${state.page} / ${max}</span>${btn('下一页','next','slim')}</div></div>`);}
