function render(){let p=location.hash.replace('#/','').split('?')[0]||'overview';if(!pages[p])p='overview';if(p!==current){state.query='';state.filter='全部';state.page=1;state.tab='';current=p;window.scrollTo(0,0);}document.title=pages[p][0]+' · TUBA 全功能原型';if(p==='login'){$('#app').innerHTML=login();return;}let n=parent[p]||p;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#/overview"><span class="brand-mark">T</span><div><strong>TUBA</strong><small>BEHAVIOR INTELLIGENCE</small></div></a>${nav.map(([g,ids])=>`<div class="navgroup">${g}</div>${ids.map(id=>`<a class="navitem ${n===id?'active':''}" href="#/${id}" ${n===id?'aria-current="page"':''}>${icon(id)}<span>${pages[id][0]}</span>${id==='anomalies'?'<span class="count">24</span>':''}</a>`).join('')}`).join('')}<div class="navfoot"><i class="dot"></i>DEMO 工作空间<br><a href="#/states" style="color:#9db9bd">界面状态规范</a> · <a href="#/login" style="color:#9db9bd">登录原型</a><br>全功能原型 v2.0</div></aside><main class="main"><header class="topbar"><div class="scope"><label>工作空间</label><select id="tenant" aria-label="工作空间">${['demo-corp','demo-lab'].map(x=>`<option ${state.tenant===x?'selected':''}>${x}</option>`).join('')}</select><span class="sep"></span><select id="time" aria-label="全局时间范围">${['最近 24 小时','最近 7 日','最近 1 小时'].map(x=>`<option ${state.time===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="top-actions"><button class="searchbtn" data-action="search">${icon('search',14)} <span>搜索页面、事件、实体</span></button><select id="page-state" class="role" aria-label="页面状态">${[['normal','正常状态'],['empty','无数据'],['forbidden','权限拒绝'],['unavailable','依赖不可用'],['loading','加载中']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><span class="prototype">原型 · 演示数据</span><div class="avatar">${state.role==='analyst'?'析':state.role==='auditor'?'审':'管'}</div><select id="role" class="role" aria-label="预览角色">${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${state.role===v?'selected':''}>${l}</option>`).join('')}</select></div></header><div class="content">${head(p)}${state.status==='normal'?renderers[p]()+workflowExtras(p):stateView()}<div class="footer-note"><span>TUBA · 可解释行为分析与调查</span><span>31 个页面视图 · 所有操作仅影响原型</span></div></div></main></div>`;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4000);}
const log=t=>state.audit.unshift(['刚刚',esc(t),'原型本地模拟']);
function close(){wizard=null;$('#overlay').innerHTML='';}
function modal(t,b,buttons=''){ $('#overlay').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${t}"><div class="modalhead"><h2>${t}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modalbody">${b}</div><div class="modalfoot">${btn('取消','close')}${buttons}</div></section></div>`;$('#overlay').querySelector('input,select,button')?.focus();}
function drawer(t,b){$('#overlay').innerHTML=`<div class="drawerback"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${t}"><div class="modalhead"><h2>${t}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modalbody">${b}</div></aside></div>`;$('#overlay').querySelector('button')?.focus();}
function field(t,c,h='',full=false){return `<div class="formfield ${full?'full':''}"><label>${t}</label>${c}${h?`<small>${h}</small>`:''}</div>`;}
