function startWizard(k){wizard={kind:k,step:0,values:{}};drawWizard();}
function drawWizard(){let w=wizard,d=wizards[w.kind];let b=`<div class="steps">${d.steps.map((x,i)=>`<div class="step ${i<=w.step?'active':''}"><b>${i+1}</b>${x}</div>`).join('')}</div>`;if(w.step===0)b+=`<form id="wizard-form"><div class="formgrid">${d.fields.map(([l,t,v],i)=>field(l,t==='select'?`<select name="field${i}">${v.split('|').map(x=>`<option>${x}</option>`).join('')}</select>`:`<input name="field${i}" required value="${v}">`)).join('')}</div></form>`;else if(w.step===1)b+=notice(d.check)+kv(Object.entries(w.values).map(([k,v])=>[d.fields[Number(k.replace('field',''))][0],esc(v)]))+`<label class="checkbox"><input id="ack" type="checkbox" checked> 已核对范围和前置条件（原型）</label>`;else b+=notice('操作仅在本地原型模拟，不会提交真实任务。')+kv([['操作',d.title],['工作空间',state.tenant],['预览角色',roles[state.role]],['审计','确认时生成原型审计记录']])+field('操作说明','<textarea rows="3" placeholder="填写调查目的或批准依据…"></textarea>');modal(d.title,b,`${w.step?btn('上一步','wizard-back'):''}${btn(w.step===2?'确认提交':'下一步','wizard-next','primary')}`);}
const infos={identity:['身份解析策略','SID / GUID 优先；弱标识必须限制 tenant、身份空间、来源与有效时间。冲突保持 ambiguous，不以最近记录覆盖。'],filter:['过滤策略 · shadow 1.0.0','批准范围内的等值合取规则。影子匹配率 2.1%，受保护事件 0。源端过滤和平台准入计数分开，平台过滤不减少来源网络流量。'],feature:['特征 Registry','UTC 左闭右开窗口；actor；qualified；allowed lateness 10m；未来时间不推进水位；去重包含 event/entity/role/feature version/generation。'],cold:['cold_start','6 完整日 / 54 样本，未达 14 完整日与 100 样本。只运行确定性规则，不输出统计评分。'],model:['不可变模型 · 1.0.0','18 日 / 432 样本；截止 10-02 23:59 UTC；算法 robust-deviation 1.0.0。样本修订后重训产生新版本，保留历史引用。'],'risk-policy':['风险计算策略','不可变正贡献、差额补偿、反向补偿；半衰期 7 日 / 30 日归零；周期衰减，关联事件去重，新旧代次不得双重累加。'],gap:['来源缺口','1102 清空 Security 日志，保留原 bookmark 与缺口证据。确认影响范围后受控恢复，不自动跳 latest。'],conflict:['Revision 内容冲突','同业务键和 revision、不同 hash。保留已有投影，冲突内容先持久 DLQ，检查确定性计算与 revision 状态。'],'agent-log':['组件日志','10:45:08 heartbeat accepted\n10:45:02 effective_config=v12\n10:44:58 queue_bytes=2516582\n只展示脱敏演示日志。'],permissions:['权限作用域','raw:read / sensitive:read / source:manage / user:manage / publisher 独立授权。API 每次检查成员有效性，下载再次授权。'],manifest:['恢复清单','PG LSN、ES snapshot、发布版本、配置哈希、审计水位逐项记录。跨库备份不是原子快照，恢复核对可重读范围。'],runbook:['分析面恢复指引','1. 按列名读取 committed / log-end / lag。\n2. 核对 PG checkpoint 和 outbox。\n3. 区分历史毒消息与新增故障。\n4. 保留缺口时按归档范围恢复。\n5. 验证 bulk 逐条结果、DLQ 确认与新鲜度。'],'audit-info':['审计详情','操作者 chen.xiao / demo-corp\n操作 case.assign / CASE-0042\n结果 succeeded / version 3 → 4\nrequest req:0a184 / trace demo-184\n追加式记录，不提供编辑删除。'],'lineage-info':['证据血缘','Raw → DIP windows 1.0.0 → UIM Authentication → SID 归因 → auth.count → finding。固定日期分区不随重试改变。'],'feedback-info':['反馈上下文','误报 / auth.failure-burst 1.1.0 / svc.backup / evt:00391。批准的服务批量认证；进入离线评估，不在线改模型。'],preferences:['工作台偏好','按角色保存调查优先级、默认 dataset、时间范围和表格密度。当前原型呈现专业调查视图。'],'quality-policy':['质量规则','qualified / partial / quarantined。partial 仅进入明确允许该质量的特征；未知枚举保留原值。'],notifications:['通知策略','receiver 未配置时显示“仅本地告警”；配置接收端后验证通知与凭据到期。'],'source-config':['版本化来源配置','期望 v13 / 生效 v12。范围、组件版本和凭据引用经过校验；不允许任意命令、任意 YAML、明文凭据回读。'],'agent-config':['下发配置','Agent 验签、应用并回报哈希；失败保持最后有效 v12。组件升级和来源上下文切换各自记录状态。'],'spl-help':['SPL 子集','支持 search 等值 / 比较 / 布尔条件、fields、sort、stats count/sum/min/max/avg by、timechart、有界 top/rare。禁止 join、eval、子查询、脚本与任意 ES DSL。']};
